fn flip_case(s: Vec<char>) -> Vec<char> {
    s.into_iter()
        .map(|c| {
            if ('a'..='z').contains(&c) {
                // ASCII lowercase -> uppercase
                ((c as u8) - b'a' + b'A') as char
            } else if ('A'..='Z').contains(&c) {
                // ASCII uppercase -> lowercase
                ((c as u8) - b'A' + b'a') as char
            } else {
                c
            }
        })
        .collect()
}